  M({ name: 'Grey Goo', icon: '🫧', r: 1, cost: 70, desc: 'Self-replicating nanomachines consume the world. VERY dangerous.', fn: (c) => { E.spawnGroup(c.w, 'grey_goo', c.x, c.y, 3, 1, { force: true }); say(c, 'Grey goo released. Good luck.', 'disaster'); } });
