  M({ name: 'Boss Rush', icon: '👑', r: 6, cost: 200, desc: 'Every boss at once. Why would you do this.', fn: (c) => { for (const k of E.monsters) { const d = E.DEFS[k]; if (d.boss && d.habitat !== 'water') E.spawn(c.w, k, c.x + U.rfloat(-c.r, c.r), c.y + U.rfloat(-c.r, c.r), { force: true }); } say(c, 'THE END TIMES ARE HERE.', 'disaster'); fx.evil(c.x, c.y, c.r); } });
  M({ name: 'Nightmare', icon: '😱', r: 5, cost: 30, desc: 'Ghosts, banshees and wraiths haunt the area.', fn: (c) => { E.spawnGroup(c.w, 'ghost', c.x, c.y, 4, c.r, { force: true }); E.spawnGroup(c.w, 'banshee', c.x, c.y, 2, c.r, { force: true }); E.spawnGroup(c.w, 'wraith', c.x, c.y, 1, c.r, { force: true }); } });
  M({ name: 'Monster Spawns (Toggle)', icon: '🌙', r: 0, cost: 20, mode: 'global', desc: 'Toggle random monster spawns across the world.', fn: (c) => { c.w.flags.monsterSpawns = !c.w.flags.monsterSpawns; toast(c, c.w.flags.monsterSpawns ? 'Monsters now roam the world.' : 'Monster spawns stopped.'); } });
  M({ name: 'Calm Monsters', icon: '😌', r: 6, cost: 10, align: 'good', desc: 'Monsters in the area stop attacking for a while.', fn: (c) => { c.w.near(c.x, c.y, c.r, (e) => { if (e.kind === 'monster') { e.data.calmed = 1200; e.target = 0; fx.hearts(e.x, e.y, 1); } }); } });
