  M({ name: 'Monster Growth', icon: '📈', r: 5, cost: 15, desc: 'Monsters here become elite.', fn: (c) => { c.w.near(c.x, c.y, c.r, (e) => { if (e.kind === 'monster') { e.maxHp *= 3; e.hp = e.maxHp; e.dmg *= 2; e.scale *= 1.3; e.name = e.name || 'Elite ' + e.def.name; fx.ring(e.x, e.y, 1, '#f00', 15, 1); } }); } });
  M({ name: 'Werewolf Curse', icon: '🌕', r: 4, cost: 20, desc: 'Humans here turn into werewolves.', fn: (c) => { const list = []; c.w.near(c.x, c.y, c.r, (e) => { if (e.kind === 'human') list.push(e); }); for (const e of list) { E.kill(c.w, e, 'curse'); e.noFx = true; E.spawn(c.w, 'werewolf', e.x, e.y, { force: true }); } } });
  M({ name: 'Vampire Lord', icon: '🧛', r: 1, cost: 40, desc: 'An ancient vampire that spreads vampirism.', fn: (c) => { const v = E.spawn(c.w, 'vampire', c.x, c.y, { force: true }); if (v) { v.maxHp = v.hp = 600; v.dmg = 45; v.scale = 1.3; v.name = 'Lord ' + U.humanName(); } } });
  M({ name: 'Kaiju Attack', icon: '🦖', r: 2, cost: 100, desc: 'A towering kaiju marches on the nearest city.', fn: (c) => { E.spawn(c.w, 'kaiju', c.x, c.y, { force: true }); say(c, 'A KAIJU emerges!', 'disaster'); if (MB.audio) MB.audio.play('roar'); } });
  M({ name: 'Dragon Flight', icon: '🐲', r: 3, cost: 120, desc: 'Three dragons descend.', fn: (c) => { for (let k = 0; k < 3; k++) E.spawn(c.w, 'dragon', c.x + U.rfloat(-2, 2), c.y + U.rfloat(-2, 2), { force: true }); say(c, 'Dragons darken the sky!', 'disaster'); } });
  M({ name: 'Pirate Fleet', icon: '🏴‍☠️', r: 3, cost: 35, desc: 'Pirates raid the coasts.', fn: (c) => { if (!TILES[c.w.get(c.tx, c.ty)].water) { toast(c, 'Place pirates on water.'); return; } E.spawnGroup(c.w, 'pirate_ship', c.x, c.y, 3, c.r, { force: true }); say(c, 'Pirates!', 'disaster'); } });
  M({ name: 'Cult Uprising', icon: '🕯️', r: 3, cost: 25, desc: 'Cultists spread corruption from this spot.', fn: (c) => { E.spawnGroup(c.w, 'cultist', c.x, c.y, 6, c.r, { force: true }); L.paintCircle(c.w, c.x, c.y, 1.5, T.CORRUPT, { onlyLand: true }); } });
  M({ name: 'Assassin', icon: '🔪', r: 1, cost: 30, desc: 'Sends an assassin to kill the nearest leader.', fn: (c) => E.spawn(c.w, 'assassin', c.x, c.y, { force: true }) });
  M({ name: 'Mind Flayer', icon: '🧠', r: 1, cost: 35, desc: 'Turns soldiers against their own people.', fn: (c) => E.spawn(c.w, 'mind_flayer', c.x, c.y, { force: true }) });

  // =========================== PEOPLE ===========================
  const P = (o) => def(Object.assign({ cat: 'People' }, o));
  P({ name: 'Spawn Human', icon: '🧍', r: 1, cost: 2, mode: 'paint', rate: 150, desc: 'Spawns a wild human. Five or more together will found a tribe!', fn: (c) => { const civ = c.w.civAt(c.tx, c.ty); const e = E.spawn(c.w, 'human', c.x + U.rfloat(-0.5, 0.5), c.y + U.rfloat(-0.5, 0.5), civ ? { civ: civ.id, role: 'civilian', home: { x: c.x, y: c.y } } : { role: 'wild' }); if (e) { c.w.playerStats.spawns++; if (civ) civ.pop += 2; if (MB.audio) MB.audio.play('spawn'); } } });
  P({ name: 'Spawn Family', icon: '👨‍👩‍👧', r: 2, cost: 6, desc: 'A family of five settles here and will found a tribe.', fn: (c) => { const es = E.spawnGroup(c.w, 'human', c.x, c.y, 5, c.r, { role: 'wild' }); const civ = c.w.civAt(c.tx, c.ty); if (civ) { for (const e of es) { e.civ = civ.id; e.role = 'civilian'; e.home = { x: c.x, y: c.y }; } civ.pop += 10; } } });
  P({ name: 'Found Civilization', icon: '🏕️', r: 3, cost: 30, align: 'good', desc: 'Found a brand new civilization right here.', fn: (c) => { const civ = C.found(c.w, c.tx, c.ty, { era: 0, pop: 15 }); if (civ) { say(c, `${cname(civ)} was founded by divine will.`, 'civ'); fx.holy(c.x, c.y, 3); if (MB.audio) MB.audio.play('achievement'); } else toast(c, 'Needs free, buildable land.'); } });
  P({ name: 'Found Advanced Civ', icon: '🏙️', r: 4, cost: 80, align: 'good', desc: 'Found a Modern Age civilization instantly.', fn: (c) => { const civ = C.found(c.w, c.tx, c.ty, { era: 6, pop: 120, radius: 5 }); if (civ) { civ.gold = 500; civ.stone = 400; civ.iron = 300; civ.wood = 300; for (let k = 0; k < 8; k++) C.buildSomewhere(c.w, civ, k < 4 ? 'tower_block' : U.pick(['factory', 'school', 'market', 'hospital']), true); say(c, `${cname(civ)} appears, fully formed.`, 'civ'); } else toast(c, 'Needs free, buildable land.'); } });
  P({ name: 'Spawn Settlers', icon: '🎒', r: 2, cost: 10, desc: 'Settlers who walk off to found a colony or new tribe.', fn: (c) => { const civ = c.civ; for (let k = 0; k < 3; k++) { const tx = U.clamp(c.x + U.rfloat(-20, 20), 1, c.w.w - 2), ty = U.clamp(c.y + U.rfloat(-20, 20), 1, c.w.h - 2); E.spawn(c.w, 'settler', c.x, c.y, { civ: civ ? civ.id : -1, ttx: tx, tty: ty, data: { pop: 6 } }); } } });
  P({ name: 'Nomad Band', icon: '🏕️', r: 2, cost: 8, desc: 'Nomads who roam and eventually settle.', fn: (c) => E.spawnGroup(c.w, 'nomad', c.x, c.y, 6, c.r) });
