  P({ name: 'Spawn Paladin', icon: '🛡️', r: 1, cost: 40, align: 'good', desc: 'A holy knight. Demons flee.', fn: (c) => E.spawn(c.w, 'paladin', c.x, c.y, { civ: c.civ ? c.civ.id : -1 }) });
  P({ name: 'Spawn Wizard', icon: '🧙', r: 1, cost: 20, align: 'good', desc: 'A wizard who hurls fireballs at monsters and heals allies.', fn: (c) => E.spawn(c.w, 'wizard', c.x, c.y, { civ: c.civ ? c.civ.id : -1, home: { x: c.x, y: c.y } }) });
  P({ name: 'Spawn Prophet', icon: '🙏', r: 1, cost: 20, align: 'good', desc: 'Sanctifies ground and lifts spirits.', fn: (c) => E.spawn(c.w, 'prophet', c.x, c.y, { civ: c.civ ? c.civ.id : -1, home: { x: c.x, y: c.y } }) });
  P({ name: 'Spawn Druid', icon: '🌿', r: 1, cost: 20, align: 'good', desc: 'Restores nature wherever they walk.', fn: (c) => E.spawn(c.w, 'druid', c.x, c.y, { home: { x: c.x, y: c.y } }) });
  P({ name: 'Spawn Trader', icon: '💰', r: 1, cost: 10, align: 'good', desc: 'A trader who ferries gold between civilizations.', fn: (c) => E.spawn(c.w, 'trader', c.x, c.y) });
