  P({ name: 'Baby Boom', icon: '👶', r: 0, cost: 20, align: 'good', desc: 'Population growth triples for a while.', fn: (c) => { if (!needCiv(c)) return; c.civ.flags.babyBoom = 600; c.civ.pop += 10; say(c, `A baby boom in ${cname(c.civ)}!`, 'good'); } });
  P({ name: 'Population +50', icon: '👥', r: 0, cost: 25, align: 'good', desc: 'Instantly add 50 people to the targeted civ.', fn: (c) => { if (!needCiv(c)) return; c.civ.pop += 50; fx.sparkle(c.civ.cx + 0.5, c.civ.cy + 0.5, '#fff', 10); } });
  P({ name: 'Population +500', icon: '🏙️', r: 0, cost: 80, align: 'good', desc: 'Add 500 people. They will need homes!', fn: (c) => { if (!needCiv(c)) return; c.civ.pop += 500; c.civ.wood += 300; c.civ.stone += 300; } });
  P({ name: 'Exodus', icon: '🚶', r: 0, cost: 25, align: 'evil', desc: 'Half the population leaves as nomads.', fn: (c) => { if (!needCiv(c)) return; const n = Math.floor(c.civ.pop * 0.5); c.civ.pop -= n; E.spawnGroup(c.w, 'nomad', c.civ.cx + 0.5, c.civ.cy + 0.5, Math.min(12, Math.ceil(n / 5)), 3); say(c, `An exodus leaves ${cname(c.civ)}.`, 'civ'); } });
  P({ name: 'Rapture', icon: '☁️', r: 8, cost: 40, align: 'neutral', desc: 'Every human in the area ascends to the heavens.', fn: (c) => { c.w.near(c.x, c.y, c.r, (e) => { if (e.kind === 'human') { e.vy = -0.5; e.habitat = 'air'; e.life = e.age + 60; e.noPop = true; fx.sparkle(e.x, e.y, '#fff', 3); } }); fx.holy(c.x, c.y, c.r); } });
  P({ name: 'Smite People', icon: '⚡', r: 4, cost: 15, align: 'evil', desc: 'Kill every human in the area.', fn: (c) => { const n = L.killIn(c.w, c.x, c.y, c.r, (e) => e.kind === 'human', 'player'); fx.lightning(c.tx, c.ty); toast(c, `${n} souls smitten.`); } });
  P({ name: 'Resurrect', icon: '⚰️', r: 4, cost: 25, align: 'good', desc: 'Graves give back their dead as living people for the nearest civ.', fn: (c) => { const n = c.civ ? Math.min(20, Math.max(3, Math.round(c.civ.deaths * 0.2))) : 5; const es = E.spawnGroup(c.w, 'human', c.x, c.y, n, c.r, c.civ ? { civ: c.civ.id, role: 'civilian', home: { x: c.x, y: c.y } } : { role: 'wild' }); if (c.civ) { c.civ.pop += es.length * 2; c.civ.deaths = 0; } fx.holy(c.x, c.y, c.r); } });
  P({ name: 'Zombify People', icon: '🧟', r: 4, cost: 20, align: 'evil', desc: 'Humans here become zombies.', fn: (c) => { const list = []; c.w.near(c.x, c.y, c.r, (e) => { if (e.kind === 'human') list.push(e); }); for (const e of list) { E.kill(c.w, e, 'curse'); e.noFx = true; E.spawn(c.w, 'zombie', e.x, e.y, { force: true }); } } });
  P({ name: 'Rename Civilization', icon: '✏️', r: 0, cost: 0, desc: 'Give the civ under the cursor a new name.', fn: (c) => { if (!needCiv(c)) return; if (c.silent) return; const n = prompt('New name for ' + cname(c.civ) + ':', c.civ.name); if (n && n.trim()) { c.civ.name = n.trim().slice(0, 24); say(c, `${cname(c.civ)} has been renamed.`, 'civ'); } } });
  P({ name: 'New Leader', icon: '👑', r: 0, cost: 10, desc: 'Replace the leader of the targeted civ.', fn: (c) => { if (!needCiv(c)) return; C.leaderDied(c.w, c.civ, 'divine decree'); for (const e of c.w.entities) if (e.type === 'leader' && e.civ === c.civ.id) { e.dead = true; e.noFx = true; } c.civ.happiness += 15; } });
  P({ name: 'Assassinate Leader', icon: '🗡️', r: 0, cost: 20, align: 'evil', desc: 'The leader of the targeted civ dies. Chaos follows.', fn: (c) => { if (!needCiv(c)) return; for (const e of c.w.entities) if (e.type === 'leader' && e.civ === c.civ.id) { E.kill(c.w, e, 'assassination'); return; } C.leaderDied(c.w, c.civ, 'assassination'); } });
  P({ name: 'Immortal Leader', icon: '♾️', r: 0, cost: 30, align: 'good', desc: 'The current leader can never die.', fn: (c) => { if (!needCiv(c)) return; for (const e of c.w.entities) if (e.type === 'leader' && e.civ === c.civ.id) { e.immortal = true; fx.sparkle(e.x, e.y, '#ffd700', 8); toast(c, `${c.civ.leader.title} ${c.civ.leader.name} is now immortal.`); return; } toast(c, 'No leader present right now.'); } });
  P({ name: 'Mass Migration', icon: '🧳', r: 0, cost: 20, desc: 'People from every other civ move to the targeted one.', fn: (c) => { if (!needCiv(c)) return; let n = 0; for (const o of c.w.civs) if (o.alive && o !== c.civ) { const m = Math.floor(o.pop * 0.15); o.pop -= m; n += m; } c.civ.pop += n; say(c, `${n} migrants arrive in ${cname(c.civ)}.`, 'civ'); } });
  P({ name: 'Inspire', icon: '🎺', r: 0, cost: 10, align: 'good', desc: 'Max out happiness for the targeted civ.', fn: (c) => { if (!needCiv(c)) return; c.civ.happiness = 100; c.civ.unrest = 0; fx.confetti(c.civ.cx + 0.5, c.civ.cy + 0.5, 20); } });
  P({ name: 'Incite Riot', icon: '🔥', r: 0, cost: 15, align: 'evil', desc: 'Happiness crashes; riots break out.', fn: (c) => { if (!needCiv(c)) return; c.civ.happiness = 5; c.civ.unrest = 50; say(c, `Unrest boils over in ${cname(c.civ)}.`, 'bad'); } });
  P({ name: 'Revolution', icon: '✊', r: 0, cost: 20, desc: 'Overthrow the government of the targeted civ.', fn: (c) => { if (!needCiv(c)) return; const govs = C.GOVS_BY_ERA[c.civ.era].filter((g) => g !== c.civ.gov); const old = cname(c.civ); c.civ.gov = govs.length ? U.pick(govs) : c.civ.gov; C.newLeader(c.civ, c.w); say(c, `Revolution! ${old} is now ${cname(c.civ)}.`, 'civ'); } });
  P({ name: 'Civil War', icon: '⚔️', r: 0, cost: 40, align: 'evil', desc: 'The targeted civ splits in two and they fight.', fn: (c) => { if (!needCiv(c)) return; if (c.civ.tiles.size < 20) { toast(c, 'Civ too small to split.'); return; } C.secede(c.w, c.civ); } });
  P({ name: 'Set Government', icon: '🏛️', r: 0, cost: 10, desc: 'Cycle the government type of the targeted civ.', fn: (c) => { if (!needCiv(c)) return; const all = ['Tribe', 'Chiefdom', 'Kingdom', 'Monarchy', 'Sultanate', 'Theocracy', 'Empire', 'Republic', 'Oligarchy', 'Democracy', 'Dictatorship', 'Federation', 'Technocracy', 'Hive', 'Cult', 'Communes', 'Anarchy']; const i = all.indexOf(c.civ.gov); c.civ.gov = all[(i + 1) % all.length]; c.civ.leader.title = U.leaderTitle(c.civ.gov, c.civ.leader.female); toast(c, `Now: ${cname(c.civ)}`); } });
  P({ name: 'Make Peaceful', icon: '🕊️', r: 0, cost: 15, align: 'good', desc: 'The targeted civ becomes pacifist.', fn: (c) => { if (!needCiv(c)) return; c.civ.personality.aggression = 0.05; if (!c.civ.traits.includes('peaceful')) c.civ.traits.push('peaceful'); c.civ.traits = c.civ.traits.filter((t) => t !== 'aggressive' && t !== 'militaristic' && t !== 'ruthless'); for (const k in c.civ.wars) C.makePeace(c.w, c.civ, c.w.civs[+k]); } });
  P({ name: 'Make Warlike', icon: '😤', r: 0, cost: 15, align: 'evil', desc: 'The targeted civ becomes bloodthirsty.', fn: (c) => { if (!needCiv(c)) return; c.civ.personality.aggression = 1; if (!c.civ.traits.includes('aggressive')) c.civ.traits.push('aggressive'); c.civ.traits = c.civ.traits.filter((t) => t !== 'peaceful' && t !== 'diplomatic'); say(c, `${cname(c.civ)} thirsts for conquest.`, 'war'); } });
  P({ name: 'Make Seafaring', icon: '⛵', r: 0, cost: 12, desc: 'The targeted civ loves the sea: ports, boats, colonies.', fn: (c) => { if (!needCiv(c)) return; c.civ.personality.sea = 1; if (!c.civ.traits.includes('seafaring')) c.civ.traits.push('seafaring'); } });
  P({ name: 'Make Scientific', icon: '🔬', r: 0, cost: 12, desc: 'The targeted civ focuses on science.', fn: (c) => { if (!needCiv(c)) return; c.civ.personality.science = 1; if (!c.civ.traits.includes('scientific')) c.civ.traits.push('scientific'); } });
  P({ name: 'Make Expansionist', icon: '🗺️', r: 0, cost: 12, desc: 'The targeted civ grabs land fast.', fn: (c) => { if (!needCiv(c)) return; c.civ.personality.expansion = 1; if (!c.civ.traits.includes('expansionist')) c.civ.traits.push('expansionist'); } });
  P({ name: 'Make Isolationist', icon: '🏝️', r: 0, cost: 12, desc: 'The targeted civ stops expanding.', fn: (c) => { if (!needCiv(c)) return; c.civ.personality.expansion = 0.1; c.civ.traits.push('isolationist'); } });
  P({ name: 'Random Traits', icon: '🎲', r: 0, cost: 8, desc: 'Reroll the personality of the targeted civ.', fn: (c) => { if (!needCiv(c)) return; const n = C.makeCiv(c.w, 0, 0, {}); c.civ.traits = n.traits; c.civ.personality = n.personality; c.w.civs.length = c.w.civs.length; toast(c, `Traits: ${c.civ.traits.join(', ')}`); } });
  P({ name: 'Convert Religion', icon: '⛪', r: 0, cost: 10, desc: 'Give the targeted civ a new faith.', fn: (c) => { if (!needCiv(c)) return; c.civ.religion = U.pick(['the Sun', 'the Sea', 'the Great Tree', 'the Ancestors', 'the Sky Father', 'the Moon Mother', 'the Machine', 'the Void', 'the Rain Bringer', 'the Flame', 'the Player', 'the Great Duck']); c.civ.faith += 30; say(c, `${cname(c.civ)} now worships ${c.civ.religion}.`, 'civ'); } });
  P({ name: 'Worship Me', icon: '🙇', r: 0, cost: 0, align: 'good', desc: 'The targeted civ worships YOU. Their faith powers your abilities.', fn: (c) => { if (!needCiv(c)) return; c.civ.religion = 'the Player'; c.civ.faith += 50; c.civ.flags.worships = 999999; c.civ.happiness += 10; say(c, `${cname(c.civ)} now worships ${c.g.settings.godName || 'you'}!`, 'good'); fx.holy(c.civ.cx + 0.5, c.civ.cy + 0.5, 4); } });
  P({ name: 'Give Name Sign', icon: '🪧', r: 0, cost: 0, desc: 'Place a sign with custom text.', fn: (c) => { if (c.silent) return; const t = prompt('Sign text:', 'Here be dragons'); if (t) E.spawn(c.w, 'sign', c.x, c.y, { name: t.slice(0, 30) }); } });
  P({ name: 'Heal People', icon: '❤️‍🩹', r: 6, cost: 6, align: 'good', desc: 'Heal all humans in the area.', fn: (c) => { c.w.near(c.x, c.y, c.r, (e) => { if (e.kind === 'human') { e.hp = e.maxHp; fx.sparkle(e.x, e.y, '#7fffd4', 2); } }); } });
  P({ name: 'Super Soldiers', icon: '💪', r: 5, cost: 20, desc: 'Soldiers here become elite veterans.', fn: (c) => { c.w.near(c.x, c.y, c.r, (e) => { if (e.type === 'soldier') { e.maxHp *= 3; e.hp = e.maxHp; e.dmg *= 2.5; e.armor = 0.4; fx.ring(e.x, e.y, 1, '#ffd700', 15, 1); } }); } });
  P({ name: 'Frog Curse', icon: '🐸', r: 4, cost: 12, align: 'evil', desc: 'People here become frogs.', fn: (c) => { const list = []; c.w.near(c.x, c.y, c.r, (e) => { if (e.kind === 'human') list.push(e); }); for (const e of list) { E.kill(c.w, e, 'witchcraft'); e.noFx = true; E.spawn(c.w, 'frog', e.x, e.y, { force: true }); fx.puff(e.x, e.y, '#4caf50', 3); } } });
  P({ name: 'Everyone Is A Cow', icon: '🐄', r: 5, cost: 15, align: 'neutral', desc: 'Moo.', fn: (c) => { const list = []; c.w.near(c.x, c.y, c.r, (e) => { if (e.kind === 'human' || e.kind === 'monster') list.push(e); }); for (const e of list) { E.kill(c.w, e, 'moo'); e.noFx = true; E.spawn(c.w, 'cow', e.x, e.y, { force: true }); } if (MB.audio) MB.audio.play('moo'); } });

  // =========================== CIVILIZATION ===========================
  const CV = (o) => def(Object.assign({ cat: 'Civilization' }, o));
  const RES = [['food', '🍖', 'Food feeds the population.'], ['wood', '🪵', 'Wood for building.'], ['stone', '🪨', 'Stone for sturdy buildings.'], ['iron', '⛓️', 'Iron for industry and war.'], ['gold', '💰', 'Gold buys everything.'], ['science', '🔬', 'Science advances eras.'], ['culture', '🎭', 'Culture expands borders and happiness.'], ['faith', '🙏', 'Faith pleases the gods (you).']];
  for (const [res, icon, desc] of RES) {
    CV({ id: 'gift_' + res, name: `Gift ${res[0].toUpperCase() + res.slice(1)}`, icon, r: 0, cost: 8, align: 'good', desc: `${desc} Gives +200 to the targeted civ.`, fn: (c) => { if (!needCiv(c)) return; c.civ[res] += 200; fx.sparkle(c.civ.cx + 0.5, c.civ.cy + 0.5, '#ffd700', 6); if (MB.audio) MB.audio.play('coin'); } });
    CV({ id: 'steal_' + res, name: `Plunder ${res[0].toUpperCase() + res.slice(1)}`, icon: '🏴‍☠️', r: 0, cost: 8, align: 'evil', desc: `Take away all ${res} from the targeted civ.`, fn: (c) => { if (!needCiv(c)) return; c.civ[res] = 0; c.civ.happiness -= 5; fx.puff(c.civ.cx + 0.5, c.civ.cy + 0.5, '#333', 6); } });
  }
  CV({ name: 'Treasure Hoard', icon: '💎', r: 0, cost: 40, align: 'good', desc: '+1000 of every resource.', fn: (c) => { if (!needCiv(c)) return; for (const [r] of RES) c.civ[r] += 1000; fx.sparkle(c.civ.cx + 0.5, c.civ.cy + 0.5, '#ffd700', 20); if (MB.audio) MB.audio.play('coin'); } });
  CV({ name: 'Bankrupt', icon: '📉', r: 0, cost: 20, align: 'evil', desc: 'Wipe out all resources of the targeted civ.', fn: (c) => { if (!needCiv(c)) return; for (const [r] of RES) c.civ[r] = 0; say(c, `${cname(c.civ)} is bankrupt.`, 'bad'); } });
  for (let era = 0; era < C.ERAS.length; era++) {
    CV({ id: 'set_era_' + era, name: `Set Era: ${C.ERAS[era]}`, icon: C.ERA_ICONS[era], r: 0, cost: 15 + era * 5, align: era >= 5 ? 'neutral' : 'neutral', desc: `Move the targeted civ to the ${C.ERAS[era]}.`, fn: (c) => { if (!needCiv(c)) return; C.setEra(c.w, c.civ, era); } });
  }
  CV({ name: 'Enlightenment', icon: '💡', r: 0, cost: 30, align: 'good', desc: 'Advance the targeted civ one era.', fn: (c) => { if (!needCiv(c)) return; C.setEra(c.w, c.civ, c.civ.era + 1); fx.holy(c.civ.cx + 0.5, c.civ.cy + 0.5, 4); } });
  CV({ name: 'Dark Age', icon: '🕯️', r: 0, cost: 30, align: 'evil', desc: 'Regress the targeted civ one era and start a dark age.', fn: (c) => { if (!needCiv(c)) return; C.setEra(c.w, c.civ, c.civ.era - 1); c.civ.darkAge = 1200; fx.evil(c.civ.cx + 0.5, c.civ.cy + 0.5, 4); } });
  CV({ name: 'Golden Age', icon: '🌟', r: 0, cost: 30, align: 'good', desc: 'The targeted civ enters a golden age: 50% more of everything.', fn: (c) => { if (!needCiv(c)) return; c.civ.goldenAge = 1500; c.civ.happiness = 100; say(c, `A golden age dawns in ${cname(c.civ)}!`, 'good'); } });
  CV({ name: 'Research Boost', icon: '🧪', r: 0, cost: 20, align: 'good', desc: 'Science needed for the next era is granted.', fn: (c) => { if (!needCiv(c)) return; c.civ.science += C.ERA_COST[c.civ.era]; } });
  CV({ name: 'Brain Drain', icon: '🧠', r: 0, cost: 15, align: 'evil', desc: 'Wipe out all accumulated science.', fn: (c) => { if (!needCiv(c)) return; c.civ.science = 0; c.civ.mods.science = 0.5; } });
  CV({ name: 'Tech Freeze', icon: '🧊', r: 0, cost: 30, mode: 'global', align: 'evil', desc: 'Toggle: no civ can advance eras.', fn: (c) => { c.w.flags.techFreeze = !c.w.flags.techFreeze; toast(c, c.w.flags.techFreeze ? 'Technology is frozen.' : 'Technology advances again.'); } });
  // build any building
  for (const key in C.BUILDINGS) {
    const bd = C.BUILDINGS[key];
    if (key === 'ruin_marker') continue;
    CV({ id: 'build_' + key, name: `Build ${bd.name}`, icon: bd.icon, r: 0, cost: bd.wonder ? 40 : 6, mode: bd.cat === 'house' || key === 'farm' || key === 'wall' ? 'paint' : 'click', rate: 180, align: 'good', desc: `Instantly build a ${bd.name} for the civ owning this tile (${C.ERAS[bd.era]}+).${bd.housing ? ` Houses ${bd.housing}.` : ''}${bd.food ? ` Food ${bd.food}.` : ''}${bd.science ? ` Science ${bd.science}.` : ''}${bd.defense ? ' Defensive.' : ''}`, fn: (c) => { let civ = c.w.civAt(c.tx, c.ty); if (!civ) { civ = L.civAtOrNear(c.w, c.tx, c.ty, 6); if (!civ) { toast(c, 'Click inside or next to a civilization.'); return; } } const t = c.w.get(c.tx, c.ty); if (!TILES[t].build || TILES[t].water) { toast(c, 'Not buildable here.'); return; } if (bd.unique && C.hasBuilding(c.w, civ, key)) { toast(c, `${civ.name} already has a ${bd.name}.`); return; } if (c.w.owner[c.i] !== civ.id) c.w.setOwner(c.i, civ.id); const b = C.build(c.w, civ, key, c.tx, c.ty, true, true); if (b) { if (MB.audio) MB.audio.play('build'); fx.debris(c.x, c.y, 6, '#c9a227'); } } });
  }
  CV({ name: 'Instant Build', icon: '🏗️', r: 0, cost: 15, align: 'good', desc: 'Finish every construction in the targeted civ.', fn: (c) => { if (!needCiv(c)) return; let n = 0; for (const j of c.civ.buildings) { const b = c.w.buildings.get(j); if (b && b.prog < 1) { C.completeBuilding(c.w, c.civ, b); n++; } } toast(c, `${n} buildings completed.`); if (MB.audio) MB.audio.play('build'); } });
  CV({ name: 'Urban Boom', icon: '🏘️', r: 0, cost: 40, align: 'good', desc: 'Build 12 era-appropriate houses in the targeted civ.', fn: (c) => { if (!needCiv(c)) return; const h = C.HOUSING[c.civ.era]; let n = 0; for (let k = 0; k < 12; k++) if (C.buildSomewhere(c.w, c.civ, h, true)) n++; toast(c, `${n} new homes.`); if (MB.audio) MB.audio.play('build'); } });
  CV({ name: 'Industrialize', icon: '🏭', r: 0, cost: 40, align: 'neutral', desc: 'Factories, mines and power plants spring up (pollution!).', fn: (c) => { if (!needCiv(c)) return; if (c.civ.era < 5) C.setEra(c.w, c.civ, 5); for (const k of ['factory', 'factory', 'deep_mine', 'power_plant', 'workshop']) C.buildSomewhere(c.w, c.civ, k, true); } });
  CV({ name: 'Fortify', icon: '🏰', r: 0, cost: 30, align: 'neutral', desc: 'Walls and towers along the border, plus a castle.', fn: (c) => { if (!needCiv(c)) return; for (let k = 0; k < 10; k++) C.buildSomewhere(c.w, c.civ, 'wall', true); for (let k = 0; k < 3; k++) C.buildSomewhere(c.w, c.civ, 'tower', true); C.buildSomewhere(c.w, c.civ, c.civ.era >= 5 ? 'fort' : 'castle', true); } });
  CV({ name: 'Wonder of the World', icon: '🏛️', r: 0, cost: 50, align: 'good', desc: 'Grant a random wonder the civ doesn\'t have yet.', fn: (c) => { if (!needCiv(c)) return; const w = C.WONDERS.filter((k) => !C.hasBuilding(c.w, c.civ, k) && k !== 'world_tree'); if (!w.length) { toast(c, 'They have every wonder!'); return; } const b = C.buildSomewhere(c.w, c.civ, U.pick(w), true); if (b) fx.holy(b.x + 0.5, b.y + 0.5, 4); } });
  CV({ name: 'Upgrade Housing', icon: '⬆️', r: 0, cost: 20, align: 'good', desc: 'All homes become the newest kind the civ knows.', fn: (c) => { if (!needCiv(c)) return; const h = C.HOUSING[c.civ.era], bd = C.BUILDINGS[h]; for (const j of c.civ.buildings) { const b = c.w.buildings.get(j); if (b && C.BUILDINGS[b.t].cat === 'house' && b.t !== h) { b.t = h; b.maxHp = b.hp = bd.hp; b.prog = 1; c.w.markDirty(b.x, b.y); } } } });
  CV({ name: 'Demolish', icon: '🧨', r: 3, cost: 4, mode: 'paint', align: 'evil', desc: 'Remove buildings in the area (leaves ruins).', fn: (c) => { c.w.forRadius(c.x, c.y, c.r, (x, y, i) => { if (c.w.buildings.has(i)) { c.w.destroyBuilding(i, true); fx.debris(x + 0.5, y + 0.5, 3); } }); } });
  CV({ name: 'Repair All', icon: '🔧', r: 0, cost: 8, align: 'good', desc: 'Fully repair every building of the targeted civ.', fn: (c) => { if (!needCiv(c)) return; for (const j of c.civ.buildings) { const b = c.w.buildings.get(j); if (b) { b.hp = b.maxHp; c.w.markDirty(b.x, b.y); } } } });
  CV({ name: 'Expand Borders', icon: '🗺️', r: 6, cost: 10, align: 'good', desc: 'Claim all land in the area for the nearest civ.', fn: (c) => { if (!needCiv(c)) return; c.w.forRadius(c.x, c.y, c.r, (x, y, i) => { if (TILES[c.w.tiles[i]].land && c.w.owner[i] < 0) c.w.setOwner(i, c.civ.id); }); C.refreshTileArr(c.civ); } });
  CV({ name: 'Annex Territory', icon: '🚩', r: 5, cost: 20, align: 'evil', desc: 'Transfer land here (and buildings) to the nearest civ, even from others.', fn: (c) => { if (!needCiv(c)) return; const tgt = c.civ; c.w.forRadius(c.x, c.y, c.r, (x, y, i) => { if (TILES[c.w.tiles[i]].land && c.w.owner[i] !== tgt.id) L.transferTile(c.w, i, tgt); }); for (const o of c.w.civs) if (o.alive) C.refreshTileArr(o); } });
  CV({ name: 'Release Land', icon: '🏳️', r: 5, cost: 5, desc: 'Make land here unclaimed (buildings become ruins).', fn: (c) => { c.w.forRadius(c.x, c.y, c.r, (x, y, i) => { if (c.w.owner[i] >= 0) { if (c.w.buildings.has(i)) c.w.destroyBuilding(i, true); c.w.setOwner(i, -1); } }); for (const o of c.w.civs) if (o.alive) C.refreshTileArr(o); } });
  CV({ name: 'Move Capital', icon: '📍', r: 0, cost: 10, desc: 'Move the targeted civ\'s capital to this tile.', fn: (c) => { if (!needCiv(c)) return; if (c.w.owner[c.i] !== c.civ.id) c.w.setOwner(c.i, c.civ.id); c.civ.cx = c.tx; c.civ.cy = c.ty; if (!c.w.buildings.has(c.i)) C.build(c.w, c.civ, c.civ.era >= 3 ? 'castle' : C.HOUSING[c.civ.era], c.tx, c.ty, true, true); toast(c, 'Capital moved.'); } });
  CV({ name: 'Declare War', icon: '⚔️', r: 0, cost: 20, align: 'evil', desc: 'The targeted civ declares war on its nearest neighbor.', fn: (c) => { if (!needCiv(c)) return; let best = null, bd = Infinity; for (const o of c.w.civs) if (o.alive && o !== c.civ && !c.civ.wars[o.id]) { const d = U.dist2(o.cx, o.cy, c.civ.cx, c.civ.cy); if (d < bd) { bd = d; best = o; } } if (best) C.declareWar(c.w, c.civ, best, 'divine command'); else toast(c, 'No one left to fight.'); } });
  CV({ name: 'War With Everyone', icon: '💢', r: 0, cost: 50, align: 'evil', desc: 'The targeted civ declares war on all others.', fn: (c) => { if (!needCiv(c)) return; for (const o of c.w.civs) if (o.alive && o !== c.civ) C.declareWar(c.w, c.civ, o, 'madness'); } });
  CV({ name: 'Force Peace', icon: '🕊️', r: 0, cost: 15, align: 'good', desc: 'End all wars of the targeted civ.', fn: (c) => { if (!needCiv(c)) return; for (const k in c.civ.wars) C.makePeace(c.w, c.civ, c.w.civs[+k]); } });
  CV({ name: 'Forge Alliance', icon: '🤝', r: 0, cost: 20, align: 'good', desc: 'Ally the targeted civ with its nearest neighbor.', fn: (c) => { if (!needCiv(c)) return; let best = null, bd = Infinity; for (const o of c.w.civs) if (o.alive && o !== c.civ && !c.civ.allies[o.id]) { const d = U.dist2(o.cx, o.cy, c.civ.cx, c.civ.cy); if (d < bd) { bd = d; best = o; } } if (best) C.ally(c.w, c.civ, best); } });
  CV({ name: 'Love Thy Neighbor', icon: '💞', r: 0, cost: 15, align: 'good', desc: 'Everyone likes the targeted civ much more.', fn: (c) => { if (!needCiv(c)) return; for (const o of c.w.civs) if (o.alive && o !== c.civ) C.changeRelation(c.w, c.civ, o, 50); } });
  CV({ name: 'Pariah', icon: '🚫', r: 0, cost: 15, align: 'evil', desc: 'Everyone hates the targeted civ.', fn: (c) => { if (!needCiv(c)) return; for (const o of c.w.civs) if (o.alive && o !== c.civ) C.changeRelation(c.w, c.civ, o, -80); } });
  CV({ name: 'Unite Civs', icon: '🫱🏻‍🫲🏽', r: 0, cost: 60, align: 'neutral', desc: 'Merge the nearest other civ into the targeted one.', fn: (c) => { if (!needCiv(c)) return; let best = null, bd = Infinity; for (const o of c.w.civs) if (o.alive && o !== c.civ) { const d = U.dist2(o.cx, o.cy, c.civ.cx, c.civ.cy); if (d < bd) { bd = d; best = o; } } if (!best) return; for (const j of Array.from(best.tiles)) L.transferTile(c.w, j, c.civ); c.civ.pop += best.pop; c.civ.gold += best.gold; for (const e of c.w.entities) if (e.civ === best.id) e.civ = c.civ.id; best.pop = 0; best.tiles.clear(); C.killCiv(c.w, best, `united with ${c.civ.name}`); C.refreshTileArr(c.civ); say(c, `${cname(best)} joined ${cname(c.civ)}.`, 'civ'); } });
