  CV({ name: 'Space Program', icon: '🚀', r: 0, cost: 60, align: 'good', desc: 'Rocket pad + launch a rocket right now.', fn: (c) => { if (!needCiv(c)) return; if (c.civ.era < 8) C.setEra(c.w, c.civ, 8); C.buildSomewhere(c.w, c.civ, 'rocket_pad', true); E.spawn(c.w, 'rocket', c.civ.cx + 0.5, c.civ.cy + 0.5, { civ: c.civ.id }); } });
  CV({ name: 'Colonize Here', icon: '🏝️', r: 2, cost: 20, align: 'good', desc: 'Found a colony of the nearest civ at this spot.', fn: (c) => { const civ = c.civ || L.nearestCiv(c.w, c.tx, c.ty); if (!civ) { toast(c, 'No civilizations exist.'); return; } C.foundColony(c.w, civ, c.tx, c.ty, 8); } });
