  CV({ name: 'Revive Fallen Civ', icon: '🕯️', r: 3, cost: 50, align: 'good', desc: 'Bring back the most recently fallen civilization at this spot.', fn: (c) => { const d = c.w.deadCivs[c.w.deadCivs.length - 1]; if (!d) { toast(c, 'No fallen civilizations.'); return; } const civ = C.found(c.w, c.tx, c.ty, { era: d.era, pop: Math.max(20, d.maxPop * 0.3), name: d.name.replace(/^(Kingdom of|Republic of|Chiefdom of|Sultanate of|Holy|United|Crown of|Cult of|Free)\s+/, '').replace(/\s+(Tribe|Empire|State|Federation|Collective|Hive|Communes|Trade League)$/, '') }); if (civ) { c.w.deadCivs.pop(); say(c, `${cname(civ)} rises again!`, 'good'); fx.holy(c.x, c.y, 4); } } });
  CV({ name: 'Statue of You', icon: '🗽', r: 0, cost: 15, align: 'good', desc: 'A monument in your honor. Faith and happiness.', fn: (c) => { if (!needCiv(c)) return; const b = C.buildSomewhere(c.w, c.civ, 'monument', true); if (b) { c.civ.faith += 50; c.civ.happiness += 10; } else toast(c, 'No room (or they already have a monument).'); } });
  CV({ name: 'Trade Route', icon: '🛤️', r: 0, cost: 15, align: 'good', desc: 'Permanent trade: the targeted civ and its nearest neighbor both gain gold now and like each other.', fn: (c) => { if (!needCiv(c)) return; let best = null, bd = Infinity; for (const o of c.w.civs) if (o.alive && o !== c.civ) { const d = U.dist2(o.cx, o.cy, c.civ.cx, c.civ.cy); if (d < bd) { bd = d; best = o; } } if (!best) return; c.civ.gold += 200; best.gold += 200; C.changeRelation(c.w, c.civ, best, 30); E.spawn(c.w, 'trader', c.civ.cx + 0.5, c.civ.cy + 0.5, { data: { dest: best.id, from: c.civ.id } }); } });
