  CV({ name: 'Roads Everywhere', icon: '🛣️', r: 0, cost: 15, align: 'good', desc: 'Pave roads between all buildings of the targeted civ.', fn: (c) => { if (!needCiv(c)) return; for (const j of c.civ.buildings) { const b = c.w.buildings.get(j); if (b) { const saved = c.civ.era; c.civ.era = Math.max(1, saved); C.completeBuilding(c.w, c.civ, b); c.civ.era = saved; } } } });
